function updateMinimumZoom(){
 const size=map.getSize();if(!size.x||!size.y)return;
 // A single Mercator world must cover both panel dimensions, including after resizing.
 const minimum=Math.max(0,Math.ceil(Math.log2(Math.max(size.x,size.y)/256)*4)/4);
 map.setMinZoom(minimum);
}
function resetMapView(){updateMinimumZoom();map.setView([50,15],map.getMinZoom(),{animate:false})}

