function setupMap(){
 map=L.map('map',{zoomControl:true,minZoom:0,maxZoom:MAP_MAX_ZOOM,zoomSnap:.25,zoomDelta:1,maxBounds:WORLD_BOUNDS,maxBoundsViscosity:1,worldCopyJump:false});
 resetMapView();
 map.on('resize',updateMinimumZoom);
 map.on('moveend zoomend',()=>{if(typeof refreshMapImageDownload==='function')refreshMapImageDownload()});
 new ResizeObserver(()=>{if($('#map').clientWidth&&$('#map').clientHeight)map.invalidateSize({pan:true,animate:false})}).observe($('#map'));
 map.createPane('catalogCoverage');map.getPane('catalogCoverage').style.zIndex=350;
 map.createPane('worldOutline');map.getPane('worldOutline').style.zIndex=150;

 // Retry a missing high-detail tile using its nearest available parent, cropped to the same footprint.
 const AvailableImagery=L.TileLayer.extend({createTile(coords,done){
  const tile=document.createElement('div'),img=document.createElement('img');
  tile.style.overflow='hidden';img.alt='';img.style.position='absolute';tile.append(img);
  let level=coords.z;
  const load=()=>{
   const factor=2**(coords.z-level),x=Math.floor(coords.x/factor),y=Math.floor(coords.y/factor),size=this.getTileSize();
   img.style.width=size.x*factor+'px';img.style.height=size.y*factor+'px';img.style.maxWidth='none';
   img.style.left=-(coords.x-x*factor)*size.x+'px';img.style.top=-(coords.y-y*factor)*size.y+'px';
   img.onload=()=>done(null,tile);
   img.onerror=()=>{if(level>0){level--;load()}else done(new Error('Imagery unavailable'),tile)};
   img.src=L.Util.template(this._url,{z:level,x,y});
  };
  load();return tile;
 }});
 let backgroundStorage;try{backgroundStorage=window.localStorage}catch{}
 const backgrounds=createBasemapController({map,TileLayer:L.TileLayer,ImageryTileLayer:AvailableImagery,select:$('#basemap-select'),labels:$('#basemap-labels'),help:$('#basemap-help'),status:$('#basemap-status'),storage:backgroundStorage});
 fetch('/vendor/world-countries.geojson').then(r=>r.json()).then(world=>backgrounds.setOutline(L.geoJSON(world,{pane:'worldOutline',style:{color:'#8da99b',weight:1,fillColor:'#c7d6c5',fillOpacity:.5},interactive:false}))).catch(()=>{});
 map.on('click',e=>{
  if(drawMode){
   const point=e.latlng;
   if(point.lng < -180||point.lng > 180||point.lat < -85||point.lat > 85){toast('Choose a point inside the world map, between 85° south and 85° north.');return}
   if(!firstCorner){firstCorner=point;return}
   const a=firstCorner,b=point;
   const bbox=[Math.min(a.lng,b.lng),Math.min(a.lat,b.lat),Math.max(a.lng,b.lng),Math.max(a.lat,b.lat)];
   if(bbox[2]-bbox[0]<.0001||bbox[3]-bbox[1]<.0001){toast('Choose a rectangle with a visible width and height.');return}
   if(drawMode==='area')drawArea(bbox,false);
   else if(drawMode==='context'){addContextRectangle(bbox)}
   else{
    const [w,s,x,n]=state.bbox;
    if(bbox[0]<w||bbox[1]<s||bbox[2]>x||bbox[3]>n){toast('The reference must be inside your analysis area.');setDraw(null);return}
    state.reference=bbox;state.referenceChoice=null;if(refRectangle)map.removeLayer(refRectangle);
    refRectangle=L.rectangle([[bbox[1],bbox[0]],[bbox[3],bbox[2]]],{color:'#4d8dd3',weight:2,fillOpacity:.15}).addTo(map);
    toast('Reference saved. Return to Set up inputs to review and run. Stability must be checked independently.');renderInputGuide();
   }
   setDraw(null);
  }else if(state.result)inspectPixel(e.latlng);
 });
}
