function confirmDeleteRun(id){
 let dialog=$('#delete-run-dialog');
 if(!dialog){dialog=document.createElement('dialog');dialog.id='delete-run-dialog';dialog.setAttribute('aria-labelledby','delete-run-title');document.body.append(dialog)}
 dialog.innerHTML=`<h2 id="delete-run-title">Delete this run?</h2><p>Run <b>${esc(id.slice(0,8))}</b> and its saved results, charts, rasters and provenance will be permanently removed. This cannot be undone.</p><p>Original NASA files, saved area extracts and the shared analysis cache will be kept.</p><p id="delete-run-error" class="error" role="alert"></p><div class="run-actions"><button class="secondary" id="cancel-delete-run" autofocus>Keep run</button><button class="primary danger-solid" id="confirm-delete-run">Delete run</button></div>`;
 $('#cancel-delete-run').onclick=()=>dialog.close();
 $('#confirm-delete-run').onclick=async()=>{
  const button=$('#confirm-delete-run');button.disabled=true;button.textContent='Deleting…';
  try{
   await api('/api/jobs/'+id,{method:'DELETE'});
   if(state.currentJob?.id===id){
    clearMapResult();
    state.currentJob=null;$('#results-section').hidden=true;$('#pixel-summary').textContent='WGS84 · latitude / longitude';
   }
   if(state.job===id){clearTimeout(state.poll);requestVersions.job++;state.job=null;$('#job-progress').hidden=true}
   dialog.close();await loadRuns();toast('Run and saved results deleted.');
  }catch(e){$('#delete-run-error').textContent=e.message;button.disabled=false;button.textContent='Delete run'}
 };
 dialog.showModal();
}
